#if UNITY_EDITOR
using System;
using System.Collections;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

// Native request replay proves UI; session projection below is an adapter, not live networking.
public static class TargetBranchPresentationValidation
{
    const string Base=".tools/target-branches-1006/ui",Native=".tools/target-branches-1006/native";
    static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
    public static string Output {get;private set;}
    public static bool Running {get;private set;}
    [Serializable] class Meta {public string folder,status,runtimeHash;}
    static Transform Root=>GameObject.Find("Canvas").transform;
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static string Hash(string file){using var h=SHA256.Create();return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(file))).Replace("-","").ToLowerInvariant();}
    static string Folder(string name){var p=Native+"/"+name+"-result.json";var m=JsonUtility.FromJson<Meta>(File.ReadAllText(p));Check(m.status=="PASS"&&m.runtimeHash==JsonUtility.FromJson<Meta>(File.ReadAllText("ForgeRuntime/runtime.json")).runtimeHash,"Incomplete/stale native "+name);File.Copy(p,Output+"/inputs/"+name+"-meta.json",true);return m.folder;}
    static ForgeSeatView Read(string name,string label){string p=Path.Combine(Folder(name),label+".json");File.Copy(p,Output+"/inputs/"+name+"-"+label+".json",true);File.AppendAllText(Output+"/input-hashes.tsv",name+"/"+label+"\t"+Hash(p)+"\n");return JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));}
    static ForgeSeatView Request(string name,Func<ForgeRequest,bool> match){foreach(string p in Directory.GetFiles(Folder(name),"step-*.json").Where(p=>!p.EndsWith("-other.json")).OrderBy(p=>int.Parse(Path.GetFileNameWithoutExtension(p).Substring(5)))){var v=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));if(match(v.request))return Read(name,Path.GetFileNameWithoutExtension(p)+(v.request.seat==2?"-other":""));}throw new Exception("No native request "+name);}
    static IEnumerator Frame(){yield return new WaitForSecondsRealtime(.2f);yield return new WaitForEndOfFrame();Canvas.ForceUpdateCanvases();}
    static void Clean(){foreach(var p in UnityEngine.Object.FindObjectsByType<ForgeBattlefieldCardPointer>(FindObjectsSortMode.None)){p.ResetHover();p.enabled=false;}}
    static void Click(Button button){Check(button!=null&&button.interactable,"Missing/disabled "+button?.name);var rect=(RectTransform)button.transform;foreach(float y in new[]{.5f,.25f,.75f})foreach(float x in new[]{.5f,.12f,.88f}){var local=new Vector2(Mathf.Lerp(rect.rect.xMin,rect.rect.xMax,x),Mathf.Lerp(rect.rect.yMin,rect.rect.yMax,y));var p=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(local)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(p,hits);if(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==button){ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,ExecuteEvents.pointerClickHandler);return;}}throw new Exception("Ray blocked "+button.name);}
    static Rect Bounds(Transform t){var c=new Vector3[4];((RectTransform)t).GetWorldCorners(c);return Rect.MinMaxRect(c.Min(p=>p.x),c.Min(p=>p.y),c.Max(p=>p.x),c.Max(p=>p.y));}
    static void DockBounds(Transform dock){foreach(var b in dock.GetComponentsInChildren<Button>()){Check(!Bounds(b.transform).Overlaps(Bounds(Root.Find("CornerCluster/ControlRow/PhaseTrack"))),"Phase covered");Check(!Bounds(b.transform).Overlaps(Bounds(Root.Find("PriorityControlMode"))),"AUTO covered");}}
    static IEnumerator Shot(string lang,string label){if(lang!="zh-CN")yield break;ScreenCapture.CaptureScreenshot(Output+"/"+label+".png");yield return Frame();}

    public static void Run(){Check(Application.isPlaying&&!Running,"Play required/already running");Running=true;Output=Base+"/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output+"/inputs");File.WriteAllText(Base+"/latest.txt",Output);File.WriteAllText(Output+"/result.txt","RUNNING");File.WriteAllText(Output+"/producer-hashes.tsv",string.Join("\n",new[]{"Assets/Scripts/Editor/TargetBranchPresentationValidation.cs","Assets/Scripts/UI/ForgeBattlefieldController.Targeting.cs","Assets/Scripts/UI/ForgeBattlefieldController.Arena.cs","Assets/Scripts/UI/ForgeBattlefieldController.LandChoices.cs","Assets/Scripts/UI/ForgeBattlefieldController.Allocation.cs","Assets/Scripts/UI/ForgeBattlefieldController.Stack.cs","Assets/Scripts/UI/ForgeBattlefieldController.BattlefieldView.cs"}.Where(File.Exists).Select(p=>p+"\t"+Hash(p))));var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("TargetBranchValidation").AddComponent<ForgeBattlefieldController>();ui.StartCoroutine(Guard(ui));}
    static IEnumerator Guard(ForgeBattlefieldController ui){var stack=new Stack<IEnumerator>();stack.Push(Validate(ui));try{while(stack.Count>0){object c;try{var e=stack.Peek();if(!e.MoveNext()){(e as IDisposable)?.Dispose();stack.Pop();continue;}c=e.Current;if(c is IEnumerator nested){stack.Push(nested);continue;}}catch(Exception error){File.WriteAllText(Output+"/result.txt","FAIL "+error);throw;}yield return c;}File.WriteAllText(Output+"/result.txt","PASS: archived native zero-target confirmation, six same-name individual identities and min/max gating, single-target reset/cancel, exact target pointer mapping, stale/duplicate/nonacting guards, View/Return font stability; native ordinary-spell division amounts/minima/reset/confirmation, Redirect stack/accept/decline/new player and end-state cleanup in three locales. Native effect results recorded separately; no all-card or live-network claim.");}finally{while(stack.Count>0)(stack.Pop() as IDisposable)?.Dispose();Running=false;}}
    static IEnumerator Show(ForgeBattlefieldController ui,ForgeSeatView v,bool act,Action<int> submit){ui.Present(null,v.seat,false,null,null,"");ui.Present(v,v.seat,act,submit,null,"");yield return new WaitForSecondsRealtime(.5f);yield return Frame();Clean();}
    static Button TargetButton(string name){var origin=GameObject.Find("TargetOrigin");Check(origin!=null,"Target origin missing");return origin.transform.Find(name).GetComponent<Button>();}
    static ForgeSeatView LastRequest(string name,Func<ForgeRequest,bool> match){foreach(string p in Directory.GetFiles(Folder(name),"step-*.json").Where(p=>!p.EndsWith("-other.json")).OrderByDescending(p=>int.Parse(Path.GetFileNameWithoutExtension(p).Substring(5)))){var v=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));if(match(v.request))return Read(name,Path.GetFileNameWithoutExtension(p)+(v.request.seat==2?"-other":""));}throw new Exception("Missing last native request "+name);}
    static void TargetClick(ForgeBattlefieldController ui,ForgeSeatView v,int id){var card=GameObject.Find("Card_"+id);Check(card!=null,"Exact target instance missing "+id);var rect=(RectTransform)card.transform;foreach(float y in new[]{.5f,.2f,.8f})foreach(float x in new[]{.5f,.2f,.8f}){var local=new Vector2(Mathf.Lerp(rect.rect.xMin,rect.rect.xMax,x),Mathf.Lerp(rect.rect.yMin,rect.rect.yMax,y));var point=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(local));if(ui.TryChooseTargetAt(point,v.request.requestId))return;}throw new Exception("Exact target ray blocked "+id);}
    static IEnumerator Validate(ForgeBattlefieldController ui){string locale=GamePreferences.Language;bool enabled=ui.enabled;ui.enabled=false;var module=EventSystem.current.currentInputModule;bool input=module!=null&&module.enabled;if(module!=null)module.enabled=false;var notices=UnityEngine.Object.FindObjectsByType<ForgeBattlefieldMigrationNotice>(FindObjectsSortMode.None);var flags=notices.Select(n=>n.enabled).ToArray();foreach(var n in notices)n.enabled=false;
        try{foreach(string lang in new[]{"zh-CN","en-US","ja-JP"}){
            int revision=GamePreferences.Revision;bool change=GamePreferences.Language!=lang;GamePreferences.SetLanguage(lang);float until=Time.realtimeSinceStartup+20;while((!GamePreferences.Ready||change&&revision==GamePreferences.Revision)&&Time.realtimeSinceStartup<until)yield return null;Check(GamePreferences.Ready,"Locale unavailable");yield return Frame();File.AppendAllText(Output+"/steps.log","requested="+lang+" loaded="+GamePreferences.Language+"\n");
            var zero=Request("finale-zero",r=>r.kind=="InputSelectTargets");int calls=0,last=-1;Action<int> submit=i=>{calls++;last=i;};yield return Show(ui,zero,true,submit);Check(zero.request.minCount==0&&zero.request.selectedCount==0&&TargetButton("ConfirmTarget").interactable,"Zero target cannot confirm");Check(!TargetButton("ResetTarget").interactable,"Invented zero reset");yield return Shot(lang,"zero-target-confirm");Click(TargetButton("ConfirmTarget"));Check(calls==1&&last==ui.OptionIndex("ok"),"Zero confirm index");
            foreach(int count in new[]{0,1,5}){
                var v=Request("hex-six",r=>r.kind=="InputSelectTargets"&&r.selectedCount==count);calls=0;last=-1;yield return Show(ui,v,true,submit);Check(!TargetButton("ConfirmTarget").interactable&&v.request.minCount==6&&v.request.maxCount==6,"Six-target gate lost");var candidates=v.request.options.Where(o=>o.card?.name=="Grizzly Bears").ToArray();Check(candidates.Length==6&&candidates.Select(o=>o.card.id).Distinct().Count()==6,"Native same-name identities lost");Check(candidates.All(o=>GameObject.Find("Card_"+o.card.id)!=null),"Same-name targets collapsed");
                var origin=GameObject.Find("TargetOrigin");int[] fonts=origin.GetComponentsInChildren<Text>().Select(t=>t.fontSize).ToArray();ui.ViewBattlefield();yield return Frame();Check(origin.GetComponent<CanvasGroup>().alpha==0,"Origin not hidden");ui.RestoreBattlefieldWindows();yield return Frame();Check(fonts.SequenceEqual(origin.GetComponentsInChildren<Text>().Select(t=>t.fontSize)),"Target font changed");var choice=candidates.First(o=>count==0||o.selected);int index=ui.OptionIndex(choice.id);Check(!ui.TrySubmitPresentedOption(index,v.request.requestId-1),"Stale target accepted");yield return Shot(lang,"same-name-"+count);TargetClick(ui,v,choice.card.id);Check(calls==1&&last==index&&!ui.TrySubmitPresentedOption(index,v.request.requestId),"Exact target/duplicate");
                yield return Show(ui,v,false,submit);Check(!TargetButton("ConfirmTarget").interactable&&!ui.TrySubmitPresentedOption(index,v.request.requestId),"Nonacting target accepted");
            }
            foreach(string control in new[]{"ConfirmTarget","ResetTarget","CancelTarget"}){
                var v=Request("shock-reset-cancel",r=>r.kind=="InputSelectTargets"&&r.selectedCount==1);calls=0;last=-1;yield return Show(ui,v,true,submit);string id=control=="ConfirmTarget"?"ok":control=="ResetTarget"?"reset-targets":"cancel";int index=ui.OptionIndex(id);Check(index>=0,"Native target control absent");Click(TargetButton(control));Check(calls==1&&last==index&&!ui.TrySubmitPresentedOption(index,v.request.requestId),"Target control index/duplicate "+control);
            }
            foreach(int remaining in new[]{1,0}){
                var division=Request("arc-partial",r=>r.kind=="AssignAmount"&&r.remainingCount==remaining);calls=0;last=-1;yield return Show(ui,division,true,submit);var panel=GameObject.Find("DamageAllocation");Check(panel!=null,"Division allocation absent");Check(panel.transform.Find("Confirm").GetComponent<Button>().interactable==(remaining==0),"Division confirmation gate");foreach(var value in division.request.allocations){var tile=panel.GetComponentsInChildren<RectTransform>().Single(t=>t.name=="Recipient_"+value.id);Check(tile.Find("Amount").GetComponent<Text>().text==value.amount.ToString()&&!tile.Find("Lethal").GetComponent<Text>().text.Contains("2"),"Spell allocation amount/combat-only hint");Check(tile.Find("Minus").GetComponent<Button>().interactable==(value.amount>1),"Spell per-target minimum");}
                yield return Shot(lang,"spell-divide-remaining-"+remaining);var action=remaining==0?panel.transform.Find("Confirm").GetComponent<Button>():panel.GetComponentsInChildren<RectTransform>().Single(t=>t.name=="Recipient_1").Find("Plus").GetComponent<Button>();string id=remaining==0?"confirm-amount":"amount-add:1";int index=ui.OptionIndex(id);Click(action);Check(calls==1&&last==index,"Spell division exact index");yield return Show(ui,division,true,submit);Click(GameObject.Find("DamageAllocation").transform.Find("Reset").GetComponent<Button>());Check(calls==2&&last==ui.OptionIndex("reset-amount"),"Spell division reset index");yield return Show(ui,division,false,submit);Check(GameObject.Find("DamageAllocation").GetComponentsInChildren<Button>().All(b=>!b.interactable),"Other seat allocation active");
            }
            foreach(int count in new[]{0,1}){
                var v=Request("redirect-change",r=>r.kind=="SelectStackTarget"&&r.selectedCount==count);calls=0;last=-1;yield return Show(ui,v,true,submit);Check(TargetButton("ConfirmTarget").interactable==(count==1)&&TargetButton("ResetTarget").interactable==(count==1),"Stack target draft controls");var target=v.request.options.Single(o=>o.id.StartsWith("stack:"));int index=ui.OptionIndex(count==1?"ok":target.id);Check(v.stackItems.Length==1&&v.stackItems[0].id.ToString()==target.id.Substring(6),"Stack row identity differs");yield return Shot(lang,"redirect-stack-"+count);Click(count==1?TargetButton("ConfirmTarget"):GameObject.Find("StackCard_0").GetComponent<Button>());Check(calls==1&&last==index,"Redirect stack pointer index");
            }
            foreach(string id in new[]{"ok","cancel"}){
                var v=Request("redirect-change",r=>r.kind=="InputConfirm");calls=0;last=-1;yield return Show(ui,v,true,submit);int index=ui.OptionIndex(id);var option=GameObject.Find("ValueOption_"+index);Check(option!=null,"Retarget optional decision absent");Click(option.GetComponent<Button>());Check(calls==1&&last==index,"Retarget accept/decline identity");
            }
            var changed=LastRequest("redirect-change",r=>r.kind=="InputSelectTargets"&&r.selectedCount==0);calls=0;last=-1;yield return Show(ui,changed,true,submit);int player=ui.OptionIndex("player:"+changed.players[0].targetId);Check(player>=0,"Original caster not legal new target");yield return Shot(lang,"redirect-new-player");Click(GameObject.Find("PlayerPlate").GetComponent<Button>());Check(calls==1&&last==player,"Retarget player exact index");
            foreach(string name in new[]{"finale-zero","hex-six","shock-reset-cancel","arc-partial","arc-all-invalid"}){ui.Present(Read(name,"resolved"),1,false,null,null,"");yield return new WaitForSecondsRealtime(.5f);yield return Frame();Check(GameObject.Find("CardAbilityChoices")==null&&GameObject.Find("CardSelection")==null&&GameObject.Find("DamageAllocation")==null,"Target/number picker retained "+name);var arrow=GameObject.Find("TargetArrow");Check(arrow==null||!arrow.activeInHierarchy,"Target arrow retained "+name);}
        }}finally{ui.Present(null,1,false,null,null,"");ui.enabled=enabled;GamePreferences.SetLanguage(locale);if(module!=null)module.enabled=input;for(int i=0;i<notices.Length;i++)if(notices[i]!=null)notices[i].enabled=flags[i];}
    }
}
#endif
